def check(output, ctx):
    try:
        call = parse_call(output)
        if not call:
            return True
        function = next((f for f in ctx["functions"] if f["name"] == call["name"]), None)
        if not function:
            return True
        required_args = function["parameters"]["required"]
        return all(arg in call.get("arguments", {}) for arg in required_args)
    except:
        return True

