def check(output, ctx):
    import re
    try:
        call = parse_call(output)
        if not call:
            return True
        args = call.get("arguments", {})
        date_pattern = re.compile(r"\d{4}-\d{2}-\d{2}")
        for value in args.values():
            if isinstance(value, str) and "birthdate" in value.lower() and not date_pattern.fullmatch(value):
                return False
        return True
    except:
        return True

